// GetShortcuts returns the keyboard shortcuts for the header (Rule 130: dynamic shortcuts)
func (m Model) GetShortcuts() shortcut.Shortcuts {
	if m.registryBrowser != nil {
		switch m.registryBrowser.state {
		case browserStateTags:
			if m.registryBrowser.filterActive {
				return []shortcut.Shortcut{
					{Key: "enter/esc", Description: "Close filter"},
				}
			}
			// enter is greyed on a tag nothing has scanned yet, rather than
			// appearing and disappearing as the cursor runs down the list
			// (Rule 130).
			return []shortcut.Shortcut{
				{Key: "enter", Description: "View CVE details",
					Disabled: !m.registryBrowser.HasSelectedTagScanResults()},
				{Key: keymap.Scan, Description: "Scan image"},
				{Key: keymap.Get, Description: "Pull image"},
				{Key: "r", Description: "Filter registry"},
				{Key: "/", Description: "Filter"},
				{Key: ".", Description: "Sort"},
				{Key: "esc", Description: "Go back"},
			}
		case browserStateImages:
			// No enter (a row has no action yet): the set of keys never
			// depends on the rows, → is greyed without one (Rule 130).
			if m.registryBrowser.searchTable.InEditMode() {
				return []shortcut.Shortcut{
					{Key: "enter/esc", Description: "Close filter"},
				}
			}
			// esc clears a confirmed query before it goes back: same key,
			// the label follows what it will do.
			escLabel := "Go back"
			if m.registryBrowser.searchTable.FilterBar().SearchQuery() != "" {
				escLabel = "Clear filter"
			}
			return []shortcut.Shortcut{
				{Key: "→", Description: "Open tags", Disabled: !m.registryBrowser.imageDrillIn().Enabled()},
				{Key: "r", Description: "Filter registry", Disabled: len(m.registryBrowser.searchFilterStops()) == 0 && m.registryBrowser.searchFilter.isEmpty()},
				{Key: "/", Description: "Filter"},
				{Key: ".", Description: "Sort"},
				{Key: "esc", Description: escLabel},
			}
		default: // browserStateInput
			// One enter entry whose label follows the focus; it is greyed on a
			// checkbox, where enter only advances. A control, not an action:
			// greying is the whole of it, and a footer line on every stray enter
			// in a form would be noise.
			enterLabel, enterLit := m.registryBrowser.FormEnter()
			return []shortcut.Shortcut{
				{Key: "enter", Description: enterLabel, Disabled: !enterLit},
				{Key: "esc", Description: "Close browser"},
			}
		}
	}
	if m.launchForm != nil {
		lf := m.launchForm
		isCheckbox := lf.isPortField(lf.focusedField) ||
			lf.focusedField == lf.fieldOptionRemove() ||
			lf.focusedField == lf.fieldOptionDetach() ||
			lf.focusedField == lf.fieldOptionInteractive()
		// The three controls a field can take, greyed rather than swapped: the
		// column changed shape on every ↑↓, in a form where the cursor moves
		// constantly (Rule 130).
		return []shortcut.Shortcut{
			{Key: "space", Description: "Toggle", Disabled: !isCheckbox},
			{Key: "←→", Description: "Cycle network", Disabled: lf.focusedField != lf.fieldNetwork()},
			{Key: "enter", Description: "Launch", Disabled: lf.focusedField != lf.fieldSubmit()},
			{Key: "ctrl+y", Description: "Copy command"},
			{Key: "esc", Description: "Cancel"},
		}
	}
	if m.resourceForm != nil {
		// Only a network has a driver to cycle, and only on its second field.
		onDriver := m.resourceForm.kind == resourceFormNetwork && m.resourceForm.focusedField == 1
		return []shortcut.Shortcut{
			{Key: "←→", Description: "Cycle driver", Disabled: !onDriver},
			{Key: "enter", Description: "Submit"},
			{Key: "esc", Description: "Cancel"},
		}
	}

// AddImageResults takes one registry's answer. It returns false, touching
// nothing, when the answer belongs to another lot. pendingSearches never goes
// below zero.
func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
	if msg.Gen != b.gen {
		return false
	}
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	oc := imagesearch.Classify(msg.Err, len(msg.Images), msg.Partial)
	if b.outcomes == nil {
		b.outcomes = map[string]imagesearch.Outcome{}
	}
	b.outcomes[msg.EntryKey] = oc
	if oc.Verdict == imagesearch.VerdictOK {
		for _, img := range msg.Images {
			img.EntryKey = msg.EntryKey
			b.images = append(b.images, img)
		}
	}
	b.rebuildSearchTable()
	return true
}

// handleImagesKeyMsg handles the keys of the level 1 table. left goes straight
// back to the form; esc acts in order: the filter bar while it is open, then a
// confirmed query, then it cancels the lot and goes back to the form (which
// keeps the typed name and the selection). The lot's late answers are no
// longer wanted and are dropped
// (TestEscAtLevelOneCancelsTheLotAndIgnoresItsLateAnswers). enter does
// nothing: a row has no action yet; → opens the row's tags.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if b.searchTable.InEditMode() {
		return b, b.searchTable.Update(msg)
	}
	switch msg.String() {
	case ".":
		b.cycleSearchSort()
		return b, nil
	case "r":
		b.cycleSearchRegistryFilter()
		return b, nil
	case "right":
		return b.openSelectedImageTags()
	case "esc":
		if bar := b.searchTable.FilterBar(); bar.SearchQuery() != "" {
			// The cursor stays on the selected row once the filter is gone.
			prev, had := b.searchTable.Selected()
			bar.ClearSearch()
			b.searchTable.SetItems(b.searchTable.Items())
			b.reselect(prev, had)
			return b, nil
		}
		return b.backToForm()
	case "left":
		return b.backToForm()
	case "enter":
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// backToForm cancels the lot and returns to the form, which keeps the typed
// name and the selection. Late answers of the lot are dropped.
func (b *RegistryBrowser) backToForm() (*RegistryBrowser, tea.Cmd) {
	b.abandonLot()
	b.state = browserStateInput
	b.searchTable.Blur()
	b.updateFocus()
	return b, nil
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	oc, _ := m.registryBrowser.Outcome(msg.EntryKey)
	alias := msg.EntryKey
	if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
		alias = entryAlias(*e)
	}
	logSearchOutcome(alias, oc, msg.Err)
	return m, nil
}

// logSearchOutcome logs a registry's verdict: failed as an error, refused as
// info, nothing for ok or no result. The cause goes through searchErrorCause,
// so no secret or typed text reaches the log.
func logSearchOutcome(alias string, oc imagesearch.Outcome, err error) {
	switch oc.Verdict {
	case imagesearch.VerdictFailed:
		log.Printf("ERROR [oci_resources] image search on %s: %s", alias, searchErrorCause(err))
	case imagesearch.VerdictRefused:
		log.Printf("INFO [oci_resources] image search on %s: unsupported or refused: %s", alias, searchErrorCause(err))
	}
}

